let selected=0,view='snapshot',file=0;const get=id=>document.getElementById(id);
function render(){const s=steps[selected];get('step-title').textContent=s.title;for(const k of ['problem','why','change','result','remaining'])get(k).textContent=s[k];get('files').replaceChildren();s.files.forEach((f,i)=>{const o=document.createElement('option');o.value=String(i);o.textContent=f.name;get('files').appendChild(o)});get('files').value=String(file);showFile();get('previous').disabled=selected===0;get('next').disabled=selected===steps.length-1;get('snapshot').setAttribute('aria-pressed',String(view==='snapshot'));get('delta').setAttribute('aria-pressed',String(view==='delta'));steps.forEach((s,i)=>get('step-'+i).setAttribute('aria-pressed',String(i===selected)));get('position').textContent='Step '+selected+' of '+(steps.length-1)}
function showFile(){const f=steps[selected].files[file];get('code').textContent=f[view]||'No code change at this checkpoint.';get('source').textContent=f.source;get('source').href=f.url}
steps.forEach((s,i)=>{const b=document.createElement('button');b.id='step-'+i;b.textContent=s.title;b.onclick=()=>{selected=i;file=0;render()};get('steps').appendChild(b)});get('files').onchange=()=>{file=Number(get('files').value);showFile()};get('previous').onclick=()=>{if(selected>0)selected--;file=0;render()};get('next').onclick=()=>{if(selected<steps.length-1)selected++;file=0;render()};get('snapshot').onclick=()=>{view='snapshot';render()};get('delta').onclick=()=>{view='delta';render()};render();